Custom Plugins:
class MyPlugin {
  apply(compiler) {
    compiler.hooks.emit.tapAsync('MyPlugin', (compilation, cb) => {
      const stats = JSON.stringify(compilation.getStats().toJson());
      compilation.assets['stats.json'] = { source: () => stats, size: () => stats.length };
      cb();
    });
  }
}

